CREATE TABLE IF NOT EXISTS gis_exception_candidate_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL, candidate_source text NOT NULL, state_name text NOT NULL, lga_name text NOT NULL, candidate_area_code text, confidence numeric NOT NULL, status text NOT NULL DEFAULT 'CANDIDATE_ONLY', evidence_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

INSERT INTO gis_ward_authority_sources (source_key,authority_name,evidence_scope,source_url,authority_level,active) SELECT 'INEC_2023_NATIONWIDE_PU_DELIMITATION','Independent National Electoral Commission (INEC)','State/LGA/Registration Area names and delimitation identifiers; not ward boundary geometry','https://www.inecnigeria.org/wp-content/uploads/2023-Polling-Unit-list-Nationwide.pdf','PRIMARY_OFFICIAL',true WHERE NOT EXISTS (SELECT 1 FROM gis_ward_authority_sources WHERE source_key='INEC_2023_NATIONWIDE_PU_DELIMITATION');